"use strict";
class Violao {
    constructor(idInstrumento, nome, preco, tipo, modelo, cordaCorpo, configEletronica, materialTampo, compEscala, orientacao, materialEscala) {
        this.idInstrumento = idInstrumento;
        this.nome = nome;
        this.preco = preco;
        this.tipo = tipo;
        this.modelo = modelo;
        this.cordaCorpo = cordaCorpo;
        this.configEletronica = configEletronica;
        this.materialTampo = materialTampo;
        this.compEscala = compEscala;
        this.orientacao = orientacao;
        this.materialEscala = materialEscala;
    }
}
class BaixoGuitarra {
    constructor(idInstrumento, nome, preco, tipo, modelo, corpCaptadores, materialCaptadores, materialBraco, materialEscala, escalaPonte, controlesEletronicos) {
        this.idInstrumento = idInstrumento;
        this.nome = nome;
        this.preco = preco;
        this.tipo = tipo;
        this.modelo = modelo;
        this.corpCaptadores = corpCaptadores;
        this.materialCaptadores = materialCaptadores;
        this.materialBraco = materialBraco;
        this.materialEscala = materialEscala;
        this.escalaPonte = escalaPonte;
        this.controlesEletronicos = controlesEletronicos;
    }
}
